export function bookValue(
  costCents: number,
  salvageCents: number,
  lifeYears: number,
  ageYears: number,
): number {
  if (ageYears < 0) {
    throw new RangeError(`ageYears cannot be negative, got ${ageYears}`);
  }
  const yearly = (costCents - salvageCents) / lifeYears;
  const used = ageYears >= lifeYears ? lifeYears : ageYears;
